-- Read-only before/after stock19 fingerprints. Excludes only the two additive nullable columns.
-- No business writes; preserves the same ledger, banks, invoices and physical stock.
select jsonb_build_object('captured_at',now(),'currency',(select currency from public.company_settings where id),'entries',(select count(*) from public.accounting_entries),'lines',(select count(*) from public.accounting_entry_lines),'debit',(select sum(debit) from public.accounting_entry_lines),'credit',(select sum(credit) from public.accounting_entry_lines),'unbalanced',(select count(*) from (select e.id from public.accounting_entries e left join public.accounting_entry_lines l on l.entry_id=e.id where e.status in('posted','reversed') group by e.id having count(l.id)<2 or coalesce(sum(l.debit-l.credit),0)<>0) x),'tables',jsonb_build_object('public.accounting_accounts',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.accounting_accounts x),
'public.accounting_journals',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.accounting_journals x),
'public.financial_accounts',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.financial_accounts x),
'public.accounting_entries',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.accounting_entries x),
'public.accounting_entry_lines',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.accounting_entry_lines x),
'public.bank_transactions',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.bank_transactions x),
'public.bank_match_groups',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.bank_match_groups x),
'public.bank_match_banks',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.bank_match_banks x),
'public.bank_match_sources',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.bank_match_sources x),
'public.reconciliations',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.reconciliations x),
'public.external_invoices',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.external_invoices x),
'public.external_invoice_payments',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.external_invoice_payments x),
'public.supplier_invoices',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.supplier_invoices x),
'public.supplier_invoice_payments',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.supplier_invoice_payments x),
'public.customer_receipts',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.customer_receipts x),
'public.accounting_periods',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.accounting_periods x),
'public.company_settings',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.company_settings x),
'private.accounting_payment_methods',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from private.accounting_payment_methods x),
'private.accounting_payment_treatments',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from private.accounting_payment_treatments x),
'private.accounting_payment_settlements',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from private.accounting_payment_settlements x),
'private.accounting_match_allocations',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from private.accounting_match_allocations x),
'private.accounting_match_postings',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from private.accounting_match_postings x),
'private.accounting_payment_preferences',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from private.accounting_payment_preferences x),
'public.stock_quants',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.stock_quants x),
'public.stock_movements',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.stock_movements x),
'public.stock_cost_layers',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.stock_cost_layers x),
'public.stock_landed_costs',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.stock_landed_costs x),
'public.stock_landed_allocations',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(x)::text,E'\n' order by to_jsonb(x)::text),''))) from public.stock_landed_allocations x),
'public.stock_cost_books',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg((to_jsonb(x)-'standard_unit_cost')::text,E'\n' order by (to_jsonb(x)-'standard_unit_cost')::text),''))) from public.stock_cost_books x),
'public.stock_valuation_entries',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg((to_jsonb(x)-'effective_on')::text,E'\n' order by (to_jsonb(x)-'effective_on')::text),''))) from public.stock_valuation_entries x))) as snapshot;
